template <typename F>
struct privDefer {
	F f;
	privDefer(F f) : f(f) {}
	~privDefer() { f(); }
};

template <typename F>
privDefer<F> defer_func(F f) {
	return privDefer<F>(f);
}

#define DEFER_1(x, y) x##y
#define DEFER_2(x, y) DEFER_1(x, y)
#define DEFER_3(x)    DEFER_2(x, __COUNTER__)
#define defer(code)   auto DEFER_3(_defer_) = defer_func([&](){code;})

import "os"

func someFunc() {
	file, err := os.Open("filename.ext", os.O_RDONLY, 0)
	if err != nil {
		// handle error
		return
	}
	defer os.Close(file)
	// Do whatever

	return // No need to close file explicitly
}

void some_func(void) {
	FILE *file = fopen("filename.ext", "rb");
	if (file == NULL) {
		// handle error
		return;
	}

	if (someTest) {
		// ...
		fclose(file); // Have to explicitly close file
		return;
	}


	fclose(file); // Have to explicit close file
}

void some_func(void) {
	FILE *file = fopen("filename.ext", "rb");
	if (file == NULL)
		return;
	defer (fclose(file));

	u8 *buffer = (u8 *)allocate(64 * sizeof(u8));
	if (buffer == NULL)
		return; // fclose is called automatically
	defer (deallocate(buffer));

	defer ({
		printf("You can even defer ");
		printf("an entire block too!");
	});

	// Do whatever...
}

void another_func(void) {
	for (int i = 0; i < 4; i++)
		defer (printf(" %d", i));
	printf(" Hello");
}
